import { AsyncLocalStorage } from 'node:async_hooks';
const ctx = new AsyncLocalStorage();

app.use((req, res, next) => {
  const traceId = req.header('traceparent')?.split('-')[1] ?? crypto.randomUUID();
  ctx.run({ traceId, path: req.path, userId: req.user?.id }, next);
});

function log(level, msg, extra = {}) {
  console.log(JSON.stringify({ level, msg, ...ctx.getStore(), ...extra, time: Date.now() }));
}
// 이제 어디서 찍든 traceId 가 자동으로 붙는다

// RED. 요청을 처리하는 서비스
//   Rate      초당 요청 수
//   Errors    오류 비율
//   Duration  응답 시간 분포 (p50, p95, p99)

// USE. 자원(CPU, 디스크, 큐)
//   Utilization  사용률
//   Saturation   대기열 길이
//   Errors       오류 수

httpDuration.observe({ route: '/order', status: 200 }, 0.042);
queueDepth.set(128);

// 대부분 자동 계측이 붙는다 (HTTP, DB, 큐)
// 필요한 곳만 손으로
const tracer = trace.getTracer('app');

await tracer.startActiveSpan('order.calculate', async (span) => {
  span.setAttribute('order.items', items.length);
  try {
    return await calculate(items);
  } catch (e) {
    span.recordException(e);
    span.setStatus({ code: SpanStatusCode.ERROR });
    throw e;
  } finally {
    span.end();
  }
});

// 나쁨: URL 을 그대로
httpTotal.inc({ path: req.url });            // /users/123?tab=1 ... 무한

// 좋음: 라우트 패턴으로
httpTotal.inc({ route: req.route?.path ?? 'unknown' });   // /users/:id

// 자세한 것은 로그, 추적에
log('info', 'request', { userId: req.user.id, url: req.url });
